'use strict';
// CIS 425 is deliberately isolated from the CIS 320 data and saved progress.
const KEY425='cis425-midterm-v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const shuffledOrder=a=>{const b=shuffle(a);if(b.length>1&&b.every((x,i)=>x===a[i]))b.push(b.shift());return b};
const paragraphs=s=>String(s||'').split(/\n+/).filter(Boolean).flatMap(p=>{const sentences=p.split(/(?<=[.!?])\s+(?=[A-Z])/),chunks=[];for(let i=0;i<sentences.length;i+=2)chunks.push(sentences.slice(i,i+2).join(' '));return chunks}).map(p=>`<p>${esc(p)}</p>`).join('');
let D,section=0,view='teach',session=null,lesson=null,storageOK=true;
let progress={cards:{},lessons:{},xp:0,days:[]};
try{const p=JSON.parse(localStorage.getItem(KEY425));if(p&&p.cards&&typeof p.cards==='object'&&!Array.isArray(p.cards)&&typeof p.xp==='number'&&Array.isArray(p.days))progress={...progress,...p,lessons:p.lessons||{}}}catch{storageOK=false}
function save(){try{localStorage.setItem(KEY425,JSON.stringify(progress))}catch{storageOK=false}stats()}
function stats(){$('#stats').innerHTML=`<span>✦ ${progress.xp} XP</span><span>${progress.days.length} study day${progress.days.length===1?'':'s'}</span>`;$('#storage-status').textContent=storageOK?'CIS 425 progress saves separately in this browser.':'Browser storage is unavailable. Progress will last only for this visit.'}
function record(x,ok){const old=progress.cards[x.id]||{seen:0,level:0};const level=ok?Math.min(6,old.level+1):0;progress.cards[x.id]={seen:old.seen+1,level,completed:old.completed||ok,due:Date.now()+(ok?[1,3,7,14,30,60][level-1]*86400000:60000)};progress.xp+=ok?10:2;const day=new Date().toLocaleDateString('en-CA');if(!progress.days.includes(day))progress.days.push(day);save()}
const filtered=items=>section?items.filter(x=>x.section===section):items;
const completed=x=>!!progress.cards[x.id]?.completed;
const sec=id=>D.sections.find(s=>s.id===id);
const source=x=>x.number?x:D.questions.find(q=>q.number===x.source);
const label=x=>`Midterm · ${sec(x.section).title}`;
function sources(x){const q=source(x);if(!q)return '';return `<details class="question-source"><summary>Sources and exam wording</summary>${q.sample?`<p><b>Professor sample: ${esc(q.sample)}</b></p>`:''}<p>${esc(q.q)}</p>${q.originalOptions?`<p>Original options: ${q.originalOptions.map(esc).join(' · ')}</p>`:''}${q.refs.map(([id,where])=>`<p class="source-note">${esc(D.sources.find(s=>s.id===id)?.name)} · ${esc(where)}</p>`).join('')}</details>`}
function picker(){if(["teach","beginner","samples","coverage","readings"].includes(view))return `<p class="tiny muted">Whole midterm</p>`;return `<label class="tiny">Midterm topic <select id="section"><option value="0">All topics</option>${D.sections.map(s=>`<option value="${s.id}" ${s.id===section?'selected':''}>${s.title}</option>`).join('')}</select></label>`}
function heading(t,p){return `<div class="heading"><div><div class="eyebrow">CIS 425 / DEFENSIVE CYBERSECURITY</div><h1>${esc(t)}</h1><p class="muted">${esc(p)}</p></div>${picker()}</div>`}
const navs=[['beginner','○','Start from zero'],['samples','☷','Professor examples'],['coverage','✓','Topic checklist'],['teach','☀','Learn First'],['practice','◈','Practice'],['flash','▤','Flashcards'],['map','▧','See the connections'],['exam','✓','Practice exam']];
const focused=[['apply','◎','Apply your knowledge'],['sort','≋','Sorting & sequences'],['abbrev','⌁','Abbreviations'],['math','#','RSA & hash lab'],['discussion','◇','Discussion practice']];
const reference=[['terms','Aa','Terms & definitions'],['guide','☷','Full answered guide'],['readings','↗','Sources & corrections']];
function buttonNav([id,icon,title]){return `<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon} &nbsp; ${title}</button>`}
function chrome(){stats();$('#nav').innerHTML=navs.map(buttonNav).join('')+`<details ${focused.some(x=>x[0]===view)?'open':''}><summary>Focused practice</summary>${focused.map(buttonNav).join('')}</details><details ${reference.some(x=>x[0]===view)?'open':''}><summary>Reference library</summary>${reference.map(buttonNav).join('')}</details>`;$('#modebar').innerHTML=`<button data-view="teach" class="${view==='teach'?'active':''}">Learn First</button><button data-view="practice" class="${view==='practice'?'active':''}">Practice Quiz</button><span class="tiny muted">CIS 425 · Midterm</span>`}
function navigate(v){$("#nav").setAttribute("data-menu-open","false");$("#study-menu").setAttribute("aria-expanded","false");view=v;session=null;lesson=null;render();window.scrollTo(0,0)}
function render(){chrome();const fn={beginner:beginnerHome,samples:samplesHome,coverage:coverageHome,teach:teachHome,practice:practiceHome,flash:flashHome,map:mapHome,exam:examHome,apply:applyHome,sort:sortHome,abbrev:abbrevHome,math:mathHome,discussion:discussionHome,terms:termsHome,guide:guideHome,readings:readingsHome}[view];fn();showSavedSession();const p=$('#section');if(p)p.onchange=()=>{section=+p.value;render()}}
function teachHome(){beginnerHome('Learn First · follow the learning path')}
function learningSequence(){return D.learningOrder.map(n=>D.questions.find(q=>q.number===n)).filter(q=>!section||q.section===section)}
function nextLearningLesson(number){const list=learningSequence(),i=list.findIndex(q=>q.number===number);return i<0?null:list[i+1]}
function learningNextLabel(number){const next=nextLearningLesson(number);return next?'Next lesson → '+next.title:'Finish learning →'}
function continueLearning(number){const q=D.questions.find(q=>q.number===number);if(!q)return;progress.lessons[q.id]=true;save();const next=nextLearningLesson(number);if(next){openLesson(next.number,0);window.scrollTo(0,0);return}const list=learningSequence(),remaining=list.filter(q=>!progress.lessons[q.id]);session=null;view='teach';chrome();$('#app').innerHTML=`<section class="card study"><h1>${remaining.length?'You reached the last lesson':'All lessons complete ✓'}</h1><p>${list.length-remaining.length} / ${list.length} lessons completed${section?' in '+esc(sec(section).title):' in this class'}.</p><div class="bar"><span style="width:${100*(list.length-remaining.length)/list.length}%"></span></div><p>${remaining.length?'Some earlier lessons are still unread. Continue with the first unfinished lesson to complete this selection.':'You’ve worked through every lesson in this selection. You can practice or revisit any lesson whenever you want.'}</p><div class="actions">${remaining.length?`<button class="primary" data-lesson="${remaining[0].number}">Continue unfinished lessons → ${lessonProgressBadge(remaining[0].number)}</button>`:'<button class="primary" data-view="practice">Practice what you learned</button>'}<button data-view="teach">All lessons</button></div></section>`;$('#app').focus();window.scrollTo(0,0)}
function openLesson(number,step=null){const target=D.questions.find(q=>q.number===number);if(!target)return;if(step===null)step=savedLessonStep(target);step=Math.max(0,Math.min(2,Number.isInteger(step)?step:0));progress.lessonSteps??={};progress.lessonSteps[target.id]=step;progress.lastLesson={number,section};save();view='teach';session=null;lesson={number,step};chrome();const q=D.questions.find(q=>q.number===number);const steps=['Start with the idea','The complete answer','A concrete example'];$('#app').innerHTML=`<div class="study"><div class="row spread"><span class="tag">${label(q)} · Lesson ${q.number} / ${D.questions.length}</span><button data-view="teach">All lessons</button></div><h1>${esc(q.title)}</h1><div class="bar"><span style="width:${100*(step+1)/3}%"></span></div><section class="card lesson-copy" style="margin-top:24px"><p class="lesson-step-label">STEP ${step+1} OF 3 · ${steps[step]}</p><h2>${esc(step===1?q.q:steps[step])}</h2>${step===0?`<p class="notice"><b>Your goal:</b> ${esc(q.goal)}</p><p><button data-view="beginner">Explain the starting vocabulary</button></p>`:""}${purposeBlock(q)}${paragraphs([q.teach,q.answer,q.example][step])}${step===2?`<div class="notice">Remember the connection: ${esc(q.correct)}</div>`:''}${sources(q)}</section><div class="actions">${step?'<button id="lesson-prev">← Back</button>':''}${step<2?'<button class="primary" id="lesson-next">Next step →</button>':`<button class="primary" id="lesson-practice">Try this topic →</button><button id="continue-learning">${esc(learningNextLabel(number))}</button>${progress.lessons[q.id]?'<span class="lesson-completed" role="status">✓ Lesson completed</span>':'<button id="lesson-complete">Mark lesson read</button>'}`}</div>${[19,39].includes(number)?'<p><button data-view="math">Open RSA & hash lab</button></p>':''}</div>`;if($('#continue-learning'))$('#continue-learning').onclick=()=>continueLearning(number);if($('#lesson-prev'))$('#lesson-prev').onclick=()=>openLesson(number,step-1);if($('#lesson-next'))$('#lesson-next').onclick=()=>openLesson(number,step+1);if($('#lesson-complete'))$('#lesson-complete').onclick=()=>{progress.lessons[q.id]=true;save();openLesson(number,2)};if($('#lesson-practice'))$('#lesson-practice').onclick=()=>{progress.lessons[q.id]=true;save();start('practice',[q,...D.cloze.filter(c=>c.source===number),...D.checks.filter(c=>c.source===number),...D.sorts.filter(c=>c.source===number).map(x=>({...x,kind:'sort'}))],number)};$('#app').focus()}
function sectionCards(){return `<div class="grid">${D.sections.map(s=>{const qs=D.questions.filter(q=>q.section===s.id),done=qs.filter(completed).length;return `<section class="card"><span class="tag">${esc(s.reading)}</span><h2>${esc(s.title)}</h2><div class="bar"><span style="width:${100*done/qs.length}%"></span></div><p>${done} / ${qs.length} lessons answered correctly${done===qs.length?' · ✓ Complete':''}</p><div class="actions"><button class="primary" data-practice-section="${s.id}">Practice this section</button></div></section>`}).join('')}</div>`}
function practiceHome(){const pool=filtered(D.questions).filter(q=>!q.uncertain),done=pool.filter(completed).length;$('#app').innerHTML=heading('Practice the study guide','Learn the words first, then apply them. Every practice round starts with concrete computer situations, followed by definitions and then application questions.')+`<section class="focus"><div><h2>${done} of ${pool.length} lessons completed</h2><p>One correct answer fills that prompt’s completion credit. Extra practice and vocabulary are tracked separately.</p><div class="actions"><button class="primary" id="quick">10 topics + their definitions</button><button id="all-guide">Practice all ${pool.length} topics + definitions</button><button id="sort-practice">Build security sequences</button><button id="blank-practice">Fill-in-the-blank choices</button><button id="recall-blanks">Recall blanks before revealing</button><button id="mixed-topic">Mix in terms & activities</button></div></div><div class="ring">${Math.round(100*done/pool.length)}%<small>COMPLETED</small></div></section>`+sectionCards()+`<div class="notice">The full answer after each question covers all parts of the original prompt. Separate term questions come before the questions that use them. Missed definition questions repeat before you move on; definitions are included again in each new practice session. Completion shows practice done, not a guarantee of exam readiness.</div>`;$('#quick').onclick=()=>{const rank=x=>{const p=progress.cards[x.id];return p?.level===0?0:!p?1:p.due<=Date.now()?2:3};start('practice',shuffle(pool).sort((a,b)=>rank(a)-rank(b)).slice(0,10))};$('#all-guide').onclick=()=>start('practice',shuffle(pool));$('#sort-practice').onclick=()=>start('practice',shuffle(filtered(D.sorts)).map(x=>({...x,kind:'sort'})));$('#recall-blanks').onclick=()=>start('flash',shuffle(filtered(D.cloze)));$('#blank-practice').onclick=()=>start('practice',shuffle(filtered(D.cloze)));$('#mixed-topic').onclick=()=>start('practice',shuffle(filtered(mixedPool())).slice(0,20))}
function mixedPool(){return [...D.questions.filter(q=>!q.uncertain),...D.checks,...D.vocab,...D.cloze,...D.sorts.map(x=>({...x,kind:'sort'})),...D.vocab.filter(x=>x.exp).map(x=>({...x,id:x.id+'-build',kind:'wordbank',q:`${["PI","AI","PO","AO"].includes(x.term)?"In the process-measurement formulas, build":"Build"} the full name of ${x.term}`}))]}
function prepare(x){if(x.kind==='cloze')return {...x,bank:shuffle([...new Set([x.correct,...x.distractors].flatMap(a=>a.split('; ')))]),picked:[]};if(x.kind==='sort')return {...x,current:shuffledOrder(x.items)};if(x.kind==='wordbank')return {...x,bank:shuffledOrder(x.exp.split(/\s+/).map((word,i)=>({word,i}))),picked:[]};return {...x,options:shuffle([x.correct,...x.distractors])}}
function start(mode,items,lessonNumber=null){if(mode==='practice'||mode==='flash')items=foundationSequence(items);if(!items.length){$('#app').innerHTML='<section class="card"><h2>No items in this selection</h2><button data-view="practice">Choose another topic</button></section>';return}session={mode,items:items.map(prepare),index:0,total:items.length,cleared:new Set(),first:{},right:0,graded:false,revealed:false,lessonNumber};session.initial=session.items.map(describeSessionItem);renderSession();window.scrollTo(0,0)}
function preteach(x){const q=source(x);return practiceDefinitions(x)+ `<details class="card"><summary>Explain this in plain language</summary><div class="lesson-copy">${purposeBlock(x)}${paragraphs(x.teach)}${q?`<p><strong>Example:</strong> ${esc(x.example||q.example)}</p>`:''}</div></details>`}
function feedback(x,ok){const q=source(x);return `<div class="feedback" role="status"><strong>${ok?'✓ Correct':'Not quite — let’s make it simple'}</strong><h3>${x.kind==='sort'?'Correct order':x.kind==='wordbank'?'Full name':'Correct answer'}</h3>${paragraphs(x.kind==='sort'?x.items.join(' → '):x.kind==='wordbank'?x.exp:x.correct)}${purposeBlock(x)}<h3>Why this fits</h3>${paragraphs(x.teach)}${q?`<h3>Picture the action</h3>${paragraphs(x.example||q.example)}<details><summary>Read the complete study-guide answer</summary>${purposeBlock(q)}${paragraphs(q.answer)}</details>`:''}${sources(x)}</div>`}
function sessionHeader(x){saveActiveSession();const s=session;return `<div class="study"><div id="session-completion-status"></div><div class="row spread"><span class="tag">${x.orientation?'Computer fundamentals':label(x)}</span><button data-view="${s.mode==='flash'?'flash':s.mode==='exam'?'exam':'practice'}">End session</button><button data-restart-session="true">Restart session</button></div><p class="tiny">${s.mode==='exam'?'Exam':s.mode==='flash'?'Flashcards':x.orientation?'Computer context':x.foundation?'Definition practice':'Apply the concept'} · ${Math.min(s.index+1,s.items.length)} / ${s.items.length}${s.mode!=='exam'&&s.mode!=='flash'?` · ${s.cleared.size}/${s.total} cleared`:''}</p><div class="bar"><span style="width:${100*(s.mode==='exam'?s.index:s.cleared.size)/s.total}%"></span></div>${s.mode==='exam'?'':practiceLocation(x)}`}
function renderSession(){const s=session;if(!s||s.index>=s.items.length){finish();return}chrome();const x=s.items[s.index];s.graded=false;s.revealed=false;if(s.mode==='flash'){renderFlash(x);return}if(x.kind==='cloze'){renderCloze(x);return}if(x.kind==='sort'){renderSort(x);return}if(x.kind==='wordbank'){renderWordBank(x);return}$('#app').innerHTML=sessionHeader(x)+`${x.format?`<p class="tiny muted">${esc(x.orientation?'Start with a concrete situation':x.foundation?'Learn one term first':x.format==='tf'?'True / False':x.format==='fill'?'Fill-in-the-blank recognition':'Concept check')}</p>`:''}<h2 class="question">${esc(x.q)}</h2>${s.mode==='exam'?'':preteach(x)}<p class="eyebrow">CHOOSE ONE ANSWER</p><div class="choices">${x.options.map((o,i)=>`<button data-option="${i}"><b>${String.fromCharCode(65+i)}.</b><span>${esc(o)}</span></button>`).join('')}</div><div id="feedback"></div></div>`;document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{if(s.graded)return;const answer=x.options[+b.dataset.option];document.querySelectorAll('[data-option]').forEach(btn=>{btn.disabled=true;if(x.options[+btn.dataset.option]===x.correct)btn.classList.add('correct')});if(answer!==x.correct)b.classList.add('wrong');grade(x,answer===x.correct,answer)})}
function renderCloze(x){let i=0;const sentence=esc(x.q).replace(/____/g,()=>{const slot=i++;return x.picked[slot]!==undefined?'<button data-blank-slot="'+slot+'" aria-label="Remove '+esc(x.bank[x.picked[slot]])+'">'+esc(x.bank[x.picked[slot]])+'</button>':'<span class="tag">Blank '+(slot+1)+'</span>'});$('#app').innerHTML=sessionHeader(x)+`<h2>Complete the sentence</h2><p class="muted">Tap a word or phrase for each blank, from left to right. Tap a filled blank to remove it.</p><section class="card lesson-copy" aria-live="polite">${sentence}</section>${session.mode==='exam'?'':preteach(x)}<div class="actions">${x.bank.map((w,j)=>`<button data-blank-word="${j}" ${x.picked.includes(j)||x.picked.length===x.blanks.length?'disabled':''}>${esc(w)}</button>`).join('')}</div><div class="actions"><button id="check-blanks" class="primary" ${x.picked.length===x.blanks.length?'':'disabled'}>Check sentence</button><button id="clear-blanks">Start over</button></div><div id="feedback"></div></div>`;document.querySelectorAll('[data-blank-word]').forEach(b=>b.onclick=()=>{if(session.graded)return;x.picked.push(+b.dataset.blankWord);renderCloze(x)});document.querySelectorAll('[data-blank-slot]').forEach(b=>b.onclick=()=>{if(session.graded)return;x.picked.splice(+b.dataset.blankSlot,1);renderCloze(x)});$('#clear-blanks').onclick=()=>{if(session.graded)return;x.picked=[];renderCloze(x)};$('#check-blanks').onclick=()=>{if(session.graded||x.picked.length!==x.blanks.length)return;const answer=x.picked.map(j=>x.bank[j]).join('; ');document.querySelectorAll('[data-blank-word],[data-blank-slot],#check-blanks,#clear-blanks').forEach(b=>b.disabled=true);grade(x,answer===x.correct,answer)}}
function grade(x,ok,selected){const s=session;if(s.graded)return;s.graded=true;s.lastOK=ok;if(!(x.id in s.first)){s.first[x.id]={ok,selected};if(ok)s.right++}if(ok)s.cleared.add(x.id);record(x,ok);$('#feedback').innerHTML=feedback(x,ok)+`<button class="primary" id="next">${s.index+1===s.items.length&&(ok||s.mode==='exam')?'See results':'Continue →'}</button>`;$('#next').onclick=advance;rememberCompletedSession(s);if(completionReady(s)){$('#feedback').insertAdjacentHTML('beforeend',completionBanner(s));$('#session-completion-status').innerHTML=completionBanner(s);$('#next').textContent='View completed session'}saveActiveSession()}
function advance(){const s=session,x=s.items[s.index];if(!s.lastOK&&s.mode!=='exam')s.items.splice(Math.min(s.index+(x.foundation?1:4),s.items.length),0,prepare(x));s.index++;renderSession();$('#app').focus()}
function finish(){const s=session;if(!s)return;rememberCompletedSession(s);try{localStorage.removeItem(SESSION425)}catch{};const missed=Object.entries(s.first).filter(([,v])=>!v.ok).map(([id])=>s.items.find(x=>x.id===id));$('#app').innerHTML=`<div class="study"><section class="card"><div class="eyebrow">CIS 425 · SESSION COMPLETE</div>${completionBanner(s)}<h1>${s.mode==='exam'?`${s.right} / ${s.total} on first attempts`:s.mode==='flash'?'✓ Flashcards completed':'✓ Completed'}</h1><p>${s.mode==='exam'?'Your score uses your first answer to each question. Review missed topics below.':`You answered or recalled all ${s.total} items successfully, including any retries.`}</p><p>${missed.length} item${missed.length===1?'':'s'} needed another look on the first attempt.</p><div class="actions"><button class="primary" data-view="practice">Back to practice</button>${missed.length?'<button id="retry-missed">Practice missed items</button>':''}${s.lessonNumber?`<button class="primary" id="continue-learning">${esc(learningNextLabel(s.lessonNumber))}</button><button data-lesson="${s.lessonNumber}">Return to the lesson ${lessonProgressBadge(s.lessonNumber)}</button>`:''}</div></section>${s.mode==='exam'?missed.map(x=>`<details class="card exam-review"><summary>${esc(x.q)}</summary>${feedback(x,false)}</details>`).join(''):''}</div>`;if(s.lessonNumber&&$('#continue-learning'))$('#continue-learning').onclick=()=>continueLearning(s.lessonNumber);if($('#retry-missed'))$('#retry-missed').onclick=()=>start('practice',shuffle(missed))}
function flashHome(){$('#app').innerHTML=heading('Flip, remember, repeat','Think of the answer, then tap the card. Mark honestly: remembered cards earn completion credit, and missed cards come back.')+`<div class="grid"><section class="card"><h2>Study-guide flashcards</h2><p>${filtered(D.questions).length} lesson prompts with complete answers.</p><button class="primary" id="flash-guide">Study guide cards</button></section><section class="card"><h2>Vocabulary flashcards</h2><p>${filtered(D.vocab).length} terms, including full abbreviation names.</p><button class="primary" id="flash-vocab">Study terms</button></section></div>`;$('#flash-guide').onclick=()=>start('flash',shuffle(filtered(D.questions)));$('#flash-vocab').onclick=()=>start('flash',shuffle(filtered(D.vocab)))}
function renderFlash(x){const s=session;$('#app').innerHTML=sessionHeader(x)+`<p class="eyebrow" id="flash-side">FRONT · TAP TO REVEAL</p><button class="card flashcard" id="flip" aria-label="Reveal answer"><h2>${esc(x.term||x.q)}</h2></button><div id="rating"></div></div>`;$('#flip').onclick=()=>{s.revealed=!s.revealed;saveActiveSession();$('#flash-side').textContent=s.revealed?'BACK · TAP TO HIDE':'FRONT · TAP TO REVEAL';$('#flip').setAttribute('aria-label',s.revealed?'Hide answer':'Reveal answer');$('#flip').innerHTML=s.revealed?`${x.exp?`<h2>${esc(x.exp)}</h2>`:''}${purposeBlock(x)}${paragraphs(x.answer)}`:`<h2>${esc(x.term||x.q)}</h2>`;$('#rating').innerHTML=s.revealed?`<div class="actions"><button id="forgot">Still learning · show again</button><button class="primary" id="remembered">I remembered it</button></div><details><summary>Help me understand</summary>${paragraphs(x.teach)}</details>`:'';if(s.revealed){$('#forgot').onclick=()=>rate(false);$('#remembered').onclick=()=>rate(true)}};function rate(ok){if(s.graded)return;s.graded=true;s.lastOK=ok;if(!(x.id in s.first)){s.first[x.id]={ok};if(ok)s.right++}if(ok)s.cleared.add(x.id);record(x,ok);advance()}}
function applyHome(){$('#app').innerHTML=heading('Apply your knowledge','Extra checks on the same guide topics, kept separate from the lesson prompts.')+`<section class="card"><h2>${filtered(D.checks).length} focused checks</h2><p>Recognize examples, distinguish similar terms, and test individual parts of multi-part guide questions.</p><button class="primary" id="apply-start">Practice these checks</button><button id="cloze-start">Fill-in-the-blank choices</button></section>`;$('#apply-start').onclick=()=>start('practice',shuffle(filtered(D.checks)));$('#cloze-start').onclick=()=>start('practice',shuffle(filtered(D.cloze)))}
function sortHome(){$('#app').innerHTML=heading('Put the steps in order','Every attempt starts shuffled. Conceptual workflows for the same midterm topics. These teach the reasoning rather than tool commands.')+`<div class="grid">${filtered(D.sorts).map(x=>`<section class="card"><h2>${esc(x.q)}</h2><p>${label(x)}</p><button class="primary" data-sort="${x.id}">Build this sequence</button></section>`).join('')}</div>${filtered(D.sorts).length?'':'<p>No sequence activities in this section. Select All topics to see them.</p>'}`}
function renderSort(x){$('#app').innerHTML=sessionHeader(x)+`<h2>${esc(x.q)}</h2>${preteach(x)}<div class="order">${x.current.map((v,i)=>`<div><b>${i+1}</b><span>${esc(v)}</span><button data-move="${i}" data-delta="-1" aria-label="Move ${esc(v)} up" ${i===0?'disabled':''}>↑</button><button data-move="${i}" data-delta="1" aria-label="Move ${esc(v)} down" ${i===x.current.length-1?'disabled':''}>↓</button></div>`).join('')}</div><button class="primary" id="check-order">Check order</button><div id="feedback"></div></div>`;document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const i=+b.dataset.move,j=i+(+b.dataset.delta);[x.current[i],x.current[j]]=[x.current[j],x.current[i]];renderSort(x)});$('#check-order').onclick=()=>{if(session.graded)return;document.querySelectorAll('[data-move],#check-order').forEach(b=>b.disabled=true);grade(x,x.current.every((v,i)=>v===x.items[i]))}}
function abbrevHome(){const items=filtered(D.vocab).filter(v=>v.exp);$('#app').innerHTML=heading('Abbreviations, fully understood','Choose the name or build it one word at a time. Then connect it to what it actually means.')+`<section class="card"><h2>${items.length} abbreviations</h2><p>${items.map(v=>esc(v.term)).join(' · ')}</p><div class="actions"><button class="primary" id="abbrev-choice">Choose the full name</button><button id="abbrev-build">Build with a word bank</button></div></section>`;$('#abbrev-choice').onclick=()=>start('practice',shuffle(items.map(v=>({...v,id:v.id+'-name',q:`${["PI","AI","PO","AO"].includes(v.term)?"In the process-measurement formulas":"In this CIS 425 course"}, what does ${v.term} stand for?`,correct:v.exp,distractors:D.abbreviationDistractors[v.term]}))));$('#abbrev-build').onclick=()=>start('practice',shuffle(items.map(v=>({...v,id:v.id+'-build',kind:'wordbank',q:`${["PI","AI","PO","AO"].includes(v.term)?"In the process-measurement formulas, build":"Build"} the full name of ${v.term}`}))))}
function renderWordBank(x){$('#app').innerHTML=sessionHeader(x)+`<h2>${esc(x.q)}</h2><p>Tap words in order. Tap a selected word to return it to the bank.</p><div class="word-answer"><div class="wordbank">${x.picked.map((v,i)=>`<button data-remove="${i}">${esc(v.word)} ×</button>`).join('')||'<span class="muted">Your answer will appear here</span>'}</div></div><div class="wordbank">${x.bank.map(v=>`<button data-word="${v.i}" ${x.picked.some(w=>w.i===v.i)?'disabled':''}>${esc(v.word)}</button>`).join('')}</div><button class="primary" id="check-bank" ${x.picked.length!==x.bank.length?'disabled':''}>Check name</button><div id="feedback"></div></div>`;document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{x.picked.push(x.bank.find(w=>w.i===+b.dataset.word));renderWordBank(x)});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{x.picked.splice(+b.dataset.remove,1);renderWordBank(x)});$('#check-bank').onclick=()=>{if(session.graded)return;document.querySelectorAll('[data-word],[data-remove],#check-bank').forEach(b=>b.disabled=true);grade(x,x.picked.map(v=>v.word).join(' ')===x.exp)}}
function termsHome(){$('#app').innerHTML=heading('Words you can actually understand','Definitions are tied to the same guide topics. Open the related lesson for context.')+`<label class="search-label">Find a term<input type="search" id="search" placeholder="Try: TCP, signature, IDS…"></label><div class="wordlist" id="terms"></div>`;function update(){const str=$('#search').value.toLowerCase(),vs=filtered(D.vocab).filter(v=>(v.term+' '+v.exp+' '+v.answer).toLowerCase().includes(str));$('#terms').innerHTML=vs.map(v=>`<article><span class="tag">${label(v)}</span><h3>${esc(v.term)}${v.exp?' · '+esc(v.exp):''}</h3>${purposeBlock(v)}${paragraphs(v.answer)}${paragraphs(v.teach)}<button data-lesson="${v.source}">See it in context ${lessonProgressBadge(v.source)}</button></article>`).join('')||'<p>No matching terms.</p>'}$('#search').oninput=update;update()}
