function examHome(){$('#app').innerHTML=heading('Practice the exam format','First answers count. These are authored practice questions, not predicted exam questions.')+`<section class="card"><h2>Midterm rehearsal</h2><p>15 true/false + 20 multiple choice + 10 fill-in-the-blank choices. Then choose 5 or 7 discussion prompts using the separate rubric. Discussion ratings are self-assessment and never added to your objective score.</p><p>Use the answer explanations to review missed concepts, then practice recalling them without choices.</p><div class="actions"><button class="primary" id="mock-exam">Start 45-question rehearsal</button><button id="topic-exam">20 questions from selected topic</button><button data-view="discussion">Discussion rehearsal</button></div></section>`;$('#mock-exam').onclick=()=>{section=0;start('exam',buildMidtermItems())};$('#topic-exam').onclick=()=>{const pool=filtered([...D.questions.filter(q=>!q.uncertain&&!['tf','fill','discussion'].includes(q.format)),...D.trueFalse,...D.cloze]);start('exam',shuffle(pool).slice(0,20))}}
const mapViews={
defense:{title:'From attack to business response',intro:'Select each stage to connect the labs with security decisions.',parts:[['Trust abuse','A believable request','Phishing and SET abuse trust. Teach verification, filter messages, and use phishing-resistant authentication.',31],['Endpoint access','A process acts on a host','Malware and keyloggers can capture data before encryption. Use least privilege, patching, application controls, and EDR.',32],['Outbound control','A reverse connection','A compromised host may connect outward. Monitor process-to-network activity and apply appropriate egress restrictions.',4],['Business response','Contain and recover','Correlate events, preserve evidence, identify affected accounts and systems, and follow containment and recovery procedures.',34]]},
keys:{title:'Whose key does what?',intro:'For confidentiality think recipient. For signatures think sender. A public key still needs a trusted identity binding.',parts:[['Encrypt for Bob','Bob’s public key','Alice protects the message so Bob can recover it using Bob’s private key.',38],['Decrypt as Bob','Bob’s private key','Bob keeps this secret. Someone holding only the public key should not be able to recover properly encrypted content.',38],['Sign as Alice','Alice’s private signing key','Alice authorizes the message. The signature does not by itself hide the message.',18],['Verify Alice','Alice’s public verification key','Bob checks the signature using a key he trusts to belong to Alice. A plain hash alone cannot establish that identity.',37]]},
chain:{title:'Bitcoin uses several mechanisms',intro:'These mechanisms solve different problems and must work together.',parts:[['Hash','Commit to data','A digest changes when data changes. SHA-256 contributes to Bitcoin hashing and proof of work.',19],['Signature','Authorize spending','The spender proves authorization under an output’s conditions using a private key, without disclosing that key.',21],['Consensus','Agree on history','Nodes validate rules and follow the valid chain with greatest cumulative proof of work.',20],['Incentive','Reward participation','Block subsidy and transaction fees motivate miners. Incentives do not eliminate all attacks or business risks.',41]]}
};
function mapHome(selected='defense'){const m=mapViews[selected];$('#app').innerHTML=heading('See the connections','Follow the security goal, evidence, and defense.')+`<div class="actions">${Object.entries(mapViews).map(([k,v])=>`<button data-map="${k}" aria-pressed="${k===selected}">${esc(v.title)}</button>`).join('')}</div><section class="card" style="margin-top:20px"><h2>${esc(m.title)}</h2><p>${esc(m.intro)}</p><div class="map-stack">${m.parts.map((p,i)=>`<button data-map-part="${i}" aria-pressed="${i===0}"><b>${esc(p[0])}</b> · ${esc(p[1])}</button>`).join('')}</div><div class="notice" id="map-detail" aria-live="polite"></div></section>`;function detail(i){const p=m.parts[i];$('#map-detail').innerHTML=`<h3>${esc(p[0])}</h3>${paragraphs(p[2])}<button data-lesson="${p[3]}">Review the lesson ${lessonProgressBadge(p[3])}</button>`;document.querySelectorAll('[data-map-part]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.mapPart===i)))}document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>mapHome(b.dataset.map));document.querySelectorAll('[data-map-part]').forEach(b=>b.onclick=()=>detail(+b.dataset.mapPart));detail(0)}

function modPow(base,exp,mod){let b=BigInt(base),e=BigInt(exp),m=BigInt(mod),r=1n;while(e>0n){if(e&1n)r=r*b%m;b=b*b%m;e>>=1n}return Number(r)}
const rsaCases=[{p:5,q:11,e:3,d:27,m:7},{p:3,q:11,e:3,d:7,m:4},{p:7,q:11,e:7,d:43,m:9}];
let rsaCase=0;
function rsaResult(c){const n=c.p*c.q,phi=(c.p-1)*(c.q-1),cipher=modPow(c.m,c.e,n);return {n,phi,cipher,plain:modPow(cipher,c.d,n)}}
function mathHome(){const c=rsaCases[rsaCase],r=rsaResult(c);$('#app').innerHTML=heading('RSA & hash lab','Work through the classroom arithmetic, then compare real SHA-256 digests.')+`<section class="card"><h2>Small RSA example</h2><p>Teaching numbers only. This is unpadded textbook RSA, unsuitable for real secrets.</p><div class="formula-grid"><div>Primes<strong>${c.p} and ${c.q}</strong></div><div>Message<strong>${c.m}</strong></div></div><div id="rsa-work"></div><div class="actions"><button class="primary" id="rsa-step">Reveal next step</button><button id="rsa-new">Different example</button><button data-lesson="39">Explain the rule ${lessonProgressBadge(39)}</button></div></section><section class="card" style="margin-top:22px"><h2>Compare original and downloaded contents</h2><p>This text simulation stands in for an original file and a downloaded copy. You initiate the check with the button below; downloading a real file does not by itself prove this comparison occurred.</p>${timelineBlock({timeline:D.hashTimeline})}<p>SHA-256 always produces 256 bits, shown as 64 hexadecimal characters. Hashing is not encryption. This comparison does not prove that collisions are impossible.</p><label>Reference contents (simulated publisher original)<input type="text" id="hash-a" value="Pay Bob 10" maxlength="300"></label><label>Downloaded contents (simulated copy)<input type="text" id="hash-b" value="Pay Bob 11" maxlength="300"></label><button id="hash-run" class="primary">Compare SHA-256 digests</button><div id="hash-output" aria-live="polite" style="overflow-wrap:anywhere"></div></section>`;const steps=[`n = p × q = ${c.p} × ${c.q} = ${r.n}.`,`φ(n) = (p − 1)(q − 1) = ${r.phi}. Choose e = ${c.e}, coprime to φ(n).`,`d = ${c.d}: e × d = ${c.e*c.d}, leaving remainder 1 modulo ${r.phi}. Public key: (${r.n}, ${c.e}); private exponent: ${c.d}.`,`Encrypt: ${c.m}^${c.e} mod ${r.n} = ${r.cipher}.`,`Decrypt: ${r.cipher}^${c.d} mod ${r.n} = ${r.plain}. The original message is recovered.`];let step=0;$('#rsa-step').onclick=()=>{if(step>=steps.length)return;$('#rsa-work').insertAdjacentHTML('beforeend',`<p class="formula-step">${esc(steps[step++])}</p>`);$('#rsa-step').disabled=step===steps.length};$('#rsa-new').onclick=()=>{rsaCase=(rsaCase+1)%rsaCases.length;mathHome()};$('#hash-run').onclick=async()=>{const output=$('#hash-output'),a=$('#hash-a').value,b=$('#hash-b').value;try{if(!globalThis.crypto?.subtle)throw Error('SHA-256 requires HTTPS or localhost in this browser.');const digest=async s=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))).map(x=>x.toString(16).padStart(2,'0')).join('');const [ha,hb]=await Promise.all([digest(a),digest(b)]);output.innerHTML=hashResultExplanation(a,b,ha,hb)}catch(e){output.textContent=e.message}}}

function startLearningModule(id){
 section=0;
 const module=D.learningModules.find(m=>m.id===id);
 if(id==='core')start('practice',[...D.basicRoute.map(id=>D.foundations.find(x=>x.id===id)),...D.checks.filter(x=>x.id.startsWith('425-first-check-'))]);
 else if(module)start('practice',module.lessons.map(n=>D.questions.find(q=>q.number===n)));
}
function beginnerHome(title='Start from zero'){
 section=0;
 $('#app').innerHTML=heading(title,'Follow the numbered path: learn the words, check their meanings, then use them in an example.')+learningResumeCard(D.learningOrder)+`<section class="card" style="margin-top:20px"><span class="tag">START HERE · NO PRIOR KNOWLEDGE</span><h2>0. Files, messages, keys, encryption, and hashes</h2><p>Data is information. An algorithm is a procedure. A key controls a cryptographic operation. Encryption hides readable information; a hash produces a summary for comparison. Learn these separately before comparing them.</p><p>Each practice session starts with concrete questions about a report on a laptop and a downloaded file, then introduces the vocabulary needed for the selected topics. Missed definition questions repeat before you move on.</p><button class="primary" data-learningmodule="core">Learn the basics one question at a time →</button><details><summary>See the core definitions</summary><dl>${D.basicRoute.map(id=>D.foundations.find(x=>x.id===id)).map(x=>`<dt><b>${esc(x.term)}</b></dt><dd>${esc(x.answer)}</dd>`).join('')}</dl></details></section>`+D.learningModules.map(module=>{const qs=module.lessons.map(n=>D.questions.find(q=>q.number===n)),done=qs.filter(q=>progress.lessons[q.id]).length;return `<section class="card" style="margin-top:22px"><h2>${esc(module.title)}</h2>${done===qs.length?'<p class="lesson-completed">✓ Completed</p>':''}<p>${done} / ${qs.length} lessons completed. Questions introduce vocabulary before asking you to apply it.</p><button data-learningmodule="${esc(module.id)}">Practice this stage with definitions</button><div class="lesson-list">${qs.map(q=>`<button data-lesson="${q.number}" class="${progress.lessons[q.id]?'lesson-is-complete':''}"><span class="badge">${q.number}</span><span class="lesson-label">${esc(q.title)}<small>${esc(q.goal)}</small></span>${lessonProgressBadge(q.number)}</button>`).join('')}</div></section>`}).join('');
 document.querySelectorAll('[data-learningmodule]').forEach(button=>button.onclick=()=>startLearningModule(button.dataset.learningmodule));
}

function samplesHome(){$('#app').innerHTML=heading('The professor’s 21 examples','Original question types and multiple-choice option order, with study answers and explanations.')+`<div class="notice">These examples illustrate the exam’s scope; they are not the whole question bank. All six discussion prompts have model answers. Use the explanations to connect each answer to the underlying concept.</div>`+['True/False','Multiple choice','Fill in the blank','Discussion'].map(type=>`<section style="margin-top:28px"><h2>${esc(type)}</h2>${D.samples.filter(x=>x.type===type).map(x=>{const q=D.questions.find(q=>q.number===x.source);return `<article class="card" style="margin-top:16px"><span class="tag">${esc(x.label)}</span><h3>${esc(x.prompt)}</h3>${x.options.length?`<ol type="A">${x.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol>`:''}<details><summary>Reveal answer and reasoning</summary><p><b>${esc(x.shortAnswer)}</b></p>${purposeBlock(q)}${paragraphs(q.answer)}${q.rubric?'<h3>A complete response includes</h3><ul>'+q.rubric.map(r=>'<li>'+esc(r)+'</li>').join('')+'</ul>':''}${sources(q)}<button data-lesson="${x.source}">Learn this step by step ${lessonProgressBadge(x.source)}</button></details></article>`}).join('')}</section>`).join('')}

function coveragePool(entry){const numbers=new Set(entry.topics.flatMap(t=>t[1]));return [...D.questions.filter(q=>numbers.has(q.number)&&!q.uncertain),...D.checks.filter(q=>numbers.has(q.source)),...D.vocab.filter(q=>numbers.has(q.source)),...D.cloze.filter(q=>numbers.has(q.source))]}
function coverageHome(){$('#app').innerHTML=heading('What each source teaches','A topic checklist tied to lessons and practice, with direct lecture and textbook coverage.')+`<div class="notice">Covered means the content and practice are present. A correct practice answer is evidence from that item, not proof of complete understanding. Review the examples, try unfamiliar scenarios, and rehearse discussions without looking at the model. The original 11 references and all 8 lecture decks have been reviewed. Videos linked inside them are not claimed as watched or transcribed.</div>${D.coverage.map(entry=>{const pool=coveragePool(entry),done=pool.filter(completed).length;return `<section class="card" style="margin-top:22px"><h2>${esc(entry.title)}</h2><p class="source-note">${esc(entry.basis)}</p><p>${done} / ${pool.length} linked practice items answered correctly at least once</p><div class="bar"><span style="width:${pool.length?100*done/pool.length:0}%"></span></div>${entry.topics.map(([title,nums])=>`<details><summary>${esc(title)}</summary><div class="actions">${nums.map(n=>`<button data-lesson="${n}">${esc(D.questions.find(q=>q.number===n).title)} ${lessonProgressBadge(n)}</button>`).join('')}</div></details>`).join('')}<button class="primary" data-coverage="${esc(entry.id)}">Practice this source’s topics</button></section>`}).join('')}`;document.querySelectorAll('[data-coverage]').forEach(b=>b.onclick=()=>{section=0;start('practice',shuffle(coveragePool(D.coverage.find(x=>x.id===b.dataset.coverage))))})}

let discussionLimit=0;
function buildMidtermItems(){const mc=[],used=new Set(),candidates=shuffle([...D.questions,...D.checks].filter(q=>!q.uncertain&&!['tf','fill','discussion'].includes(q.format)));function take(section){const q=candidates.find(q=>(!section||q.section===section)&&!used.has(q.number||q.source));if(q){mc.push(q);used.add(q.number||q.source)}}for(const section of D.sections)for(let i=0;i<2;i++)take(section.id);while(mc.length<20){const before=mc.length;take(0);if(mc.length===before)break}return [...shuffle(D.trueFalse).slice(0,15),...shuffle(mc),...shuffle(D.cloze).slice(0,10)]}
function discussionHome(){const pool=D.discussions.filter(q=>!section||q.section===section),qs=discussionLimit?shuffle(pool).slice(0,discussionLimit):pool;$('#app').innerHTML=heading('Explain it before revealing it','Rehearse out loud or on paper. Then compare your reasoning with the model and rubric.')+`<div class="notice">Self-assessment only: the app does not automatically grade written or spoken answers. Define the concept, explain the mechanism, apply it to a business, and mention a limitation. The six professor examples and one added lab/business scenario form this discussion bank.</div><div class="actions"><button id="discussion-five">Rehearse 5 from all topics</button><button id="discussion-seven">Rehearse all 7</button></div>${qs.map(q=>`<section class="card" style="margin-top:20px"><span class="tag">${esc(q.sample||'Added lab/business scenario')}</span><h2>${esc(q.q)}</h2><p>Try a 2–3 minute explanation before opening the model.</p><details><summary>Reveal model answer and checklist</summary>${purposeBlock(q)}${paragraphs(q.answer)}<h3>Check your coverage</h3>${q.rubric.map((r,i)=>`<label style="display:block;padding:10px"><input type="checkbox" data-rubric="${q.id}-${i}" ${progress.rubrics?.[q.id+'-'+i]?'checked':''}> ${esc(r)}</label>`).join('')}<p class="tiny">A check records your judgment; it does not verify correctness.</p>${sources(q)}<button data-lesson="${q.number}" class="${progress.lessons[q.id]?'lesson-is-complete':''}">Review this lesson ${lessonProgressBadge(q.number)}</button></details></section>`).join('')}`;document.querySelectorAll('[data-rubric]').forEach(b=>b.onchange=()=>{progress.rubrics??={};progress.rubrics[b.dataset.rubric]=b.checked;save()});$('#discussion-five').onclick=()=>{section=0;discussionLimit=5;discussionHome()};$('#discussion-seven').onclick=()=>{section=0;discussionLimit=7;discussionHome()}}

function savedLessonStep(q){const value=progress.lessonSteps?.[q.id];return Number.isInteger(value)&&value>=0&&value<=2?value:0}
function lessonProgressBadge(number){
 const q=D.questions.find(q=>q.number===number);if(!q)return '';
 const done=!!progress.lessons[q.id],started=Object.hasOwn(progress.lessonSteps||{},q.id);
 return `<span class="lesson-state ${done?'is-complete':''}">${done?'✓ Completed':started?'Resume · Step '+(savedLessonStep(q)+1)+' of 3':'Not started'}</span>`;
}
function learningResumeCard(route){
 const list=route?route.map(n=>D.questions.find(q=>q.number===n)).filter(Boolean):learningSequence(),last=progress.lastLesson;
 const q=list.find(q=>q.number===last?.number)||list.find(q=>!progress.lessons[q.id]);
 if(!q)return '<p class="lesson-completed" role="status">✓ All lessons in this selection completed</p>';
 const step=savedLessonStep(q),visited=Object.hasOwn(progress.lessonSteps||{},q.id);
 return `<section class="card learning-resume"><span class="tag">${visited?'YOUR SAVED PLACE':'UP NEXT'}</span><h2>${esc(q.title)}</h2><p>Lesson ${q.number} · ${visited?'Step '+(step+1)+' of 3':'Not started'}${progress.lessons[q.id]?' · Completed — available to review':''}</p><button class="primary" data-lesson="${q.number}">${visited?'Resume this lesson':'Start learning'} →</button><p class="tiny">Your place and completed lessons save in this browser.</p></section>`;
}

function prerequisiteIds(x){return D.prerequisites[x.id]||D.prerequisites[x.id.replace(/-build$/,'')]||D.prerequisites[source(x)?.id]||[]}
function foundationSequence(items){
 const lookup=new Map([...D.vocab,...D.foundations,...D.orientation,...D.topicOrientation].map(x=>[x.id,x]));
 const scheduled=new Set(),visiting=new Set(),result=[];
 function add(x,context){
  if(scheduled.has(x.id)||visiting.has(x.id))return;
  visiting.add(x.id);
  if(!x.foundation&&!x.term&&x.topicIntroId){const intro=lookup.get(x.topicIntroId);if(intro)add(intro,context)}
  for(const id of prerequisiteIds(x)){const prerequisite=lookup.get(id);if(prerequisite)add({...prerequisite,foundation:true},context)}
  visiting.delete(x.id);
  if(!scheduled.has(x.id)){scheduled.add(x.id);result.push(x.term?{...x,foundation:true,preparingFor:context}:x.orientation?{...x,preparingFor:context}:x)}
 }
 for(const x of D.orientation)add(x,'Files, messages, encryption, and file comparison');
 for(const id of D.basicRoute||[]){const x=lookup.get(id);if(x)add(x,'Computer and cryptography basics')}
 const rank=new Map((D.learningOrder||[]).map((n,i)=>[n,i]));
 const ordered=[...items].sort((a,b)=>(rank.get(a.number||a.source)??999)-(rank.get(b.number||b.source)??999));
 for(const x of ordered)add(x,source(x)?.title||x.term||'This topic');
 return result;
}
function practiceLocation(x){
 const topic=source(x),module=D.learningModules?.find(m=>m.lessons.includes(topic?.number));
 return `<section class="practice-location"><p><b>${x.orientation?'Computer context':x.foundation?'Learning a term':'Applying the concept'}:</b> ${esc(x.orientation?'Files, messages, encryption, and file comparison':x.term||topic?.title||'Midterm practice')}</p><p>${x.foundation?'Preparing for: '+esc(x.preparingFor||topic?.title||'Core vocabulary'):esc(module?.title||'Midterm review')}</p></section>`+computerSetting(x);
}
function computerSetting(x){
 if(x.orientation)return `<section class="card computer-setting"><p>${esc(x.context)}</p></section>`;
 const setting=x.setting||D.topicContexts[String(x.number||x.source)]||D.practicalContexts[x.contextKey||source(x)?.contextKey];
 return setting?`<section class="card computer-setting">${setting.focus?`<p><b>Current focus:</b> ${esc(setting.focus)}</p>`:''}<p><b>Situation:</b> ${esc(setting.object)}</p><p><b>Location:</b> ${esc(setting.location)}</p>${x.topicOrientation?'':`<p><b>Security task:</b> ${esc(setting.purpose)}</p>`}${setting.example&&setting.example!==setting.object?`<p><b>Concrete example:</b> ${esc(setting.example)}</p>`:''}<details><summary>What happens and why it matters</summary><p>${esc(setting.action)}</p></details></section>`:'';
}
function examSetting(x){
 const setting=x.setting||D.topicContexts[String(x.number||x.source)];
 return setting?`<details class="card computer-setting"><summary>Scenario context</summary><p><b>Situation:</b> ${esc(setting.object)}</p><p><b>Location:</b> ${esc(setting.location)}</p></details>`:'';
}
function purposeBlock(x){
 const purpose=x.purpose||source(x)?.purpose;
 return purpose?`<section class="concept-purpose"><h3>Purpose</h3>${paragraphs(purpose)}${resultWalkthrough(x)}</section>`:'';
}
function resultWalkthrough(x){
 const flow=x.walkthrough||source(x)?.walkthrough;if(!flow)return '';
 return `<dl class="result-walkthrough">${[['Starting point','starting'],['What happens','operation'],['Result','result'],['How the result is used','use']].map(([label,key])=>`<dt><b>${label}</b></dt><dd>${esc(flow[key])}</dd>`).join('')}</dl>${timelineBlock(x)}${flow.workedExample?`<details class="worked-result"><summary>Worked example with actual values</summary><p>${esc(flow.workedExample)}</p></details>`:''}`;
}
function timelineBlock(x){
 const steps=x.timeline||source(x)?.timeline;
 return steps?.length?`<details class="concept-timeline" open><summary>Timeline: who does what and when</summary><ol>${steps.map(step=>`<li><b>${esc(step.when)}</b><p><strong>${esc(step.who)}:</strong> ${esc(step.event)}</p></li>`).join('')}</ol></details>`:'';
}
function hashResultExplanation(a,b,ha,hb){
 return `<h3>1. Reference calculation</h3><p>The program read the reference text: <b>${esc(a)}</b>.</p><p>Calculated hash value: <code>${esc(ha)}</code></p><h3>2. Download calculation</h3><p>The program read your simulated downloaded text: <b>${esc(b)}</b>.</p><p>Calculated hash value: <code>${esc(hb)}</code></p><h3>3. Compare the two calculated values</h3><p>${ha===hb?'The values match. In this example, the comparison supports matching contents.':'The values differ. The supplied contents differ; the simulated copy does not match the reference.'}</p><h3>4. Use the result</h3><p>${ha===hb?'For a real download, also establish that the reference comes from a trusted source for the exact release. A hash match alone does not certify that software is harmless.':'For a real download, investigate or obtain the correct file before relying on it. A mismatch does not say whether the cause was an error, a legitimate different version, or an attacker.'}</p><p>These calculations did not encrypt, repair, or replace either text. This is a text simulation; a file-checking tool reads the actual file’s bytes.</p>`;
}
function practiceDefinitions(x){
 const lookup=new Map([...D.vocab,...D.foundations].map(v=>[v.id,v]));
 const defs=prerequisiteIds(x).map(id=>lookup.get(id)).filter(v=>v?.foundation);
 return defs.length?`<details class="card practice-glossary"><summary>Words in this question · ${defs.length} definitions</summary><dl>${defs.map(v=>`<dt><b>${esc(v.term)}</b>${v.exp?' · '+esc(v.exp):''}</dt><dd>${esc(v.answer)}</dd>`).join('')}</dl></details>`:'';
}

const SESSION425=KEY425+'-active-session';
function sessionCatalog(){return new Map([...D.questions,...D.checks,...D.vocab,...D.foundations,...D.orientation,...D.topicOrientation,...D.trueFalse,...D.cloze,...D.sorts].map(x=>[x.id,x]))}
function describeSessionItem(x){const result={id:x.id};for(const k of ['kind','options','bank','picked','current','foundation','preparingFor','q','exp'])if(x[k]!==undefined)result[k]=x[k];return result}
function restoreSessionItem(saved,catalog){
 const base=catalog.get(saved.id)||catalog.get(saved.id.replace(/-build$/,''));
 return base?{...base,...saved}:null;
}
function saveActiveSession(){
 if(!session||session.index>=session.items.length)return;
 try{
  const saved={version:1,mode:session.mode,section,index:session.index,total:session.total,right:session.right,cleared:[...session.cleared],first:session.first,graded:session.graded,lastOK:session.lastOK,revealed:session.revealed,completionRecorded:session.completionRecorded,lessonNumber:session.lessonNumber,items:session.items.map(describeSessionItem),initial:session.initial||session.items.map(describeSessionItem)};
  localStorage.setItem(SESSION425,JSON.stringify(saved));
 }catch{storageOK=false;stats()}
}
function readActiveSession(){
 try{
  const saved=JSON.parse(localStorage.getItem(SESSION425));
  if(!saved||saved.version!==1||!['practice','flash','exam'].includes(saved.mode)||!Array.isArray(saved.items)||!Number.isInteger(saved.index)||saved.index<0||saved.index>=saved.items.length)return null;
  const catalog=sessionCatalog(),items=saved.items.map(x=>restoreSessionItem(x,catalog));
  if(items.some(x=>!x)||!Array.isArray(saved.cleared)||!saved.first||!Number.isInteger(saved.total)||saved.total<1)return null;
  return {...saved,items};
 }catch{return null}
}
function savedSessionMarkup(){
 const saved=readActiveSession();if(!saved)return '';
 const x=saved.items[saved.index];
 return `<section class="card saved-practice" id="saved-practice"><span class="tag">SAVED PRACTICE</span><h2>Continue where you left off</h2><p><b>Question ${saved.index+1} of ${saved.items.length}</b> · ${saved.cleared.length} / ${saved.total} items completed</p><p>${esc(x.q)}</p><div class="actions"><button class="primary" id="resume-saved-practice">Resume saved ${saved.mode==='exam'?'exam':saved.mode==='flash'?'flashcards':'practice'}</button><button id="restart-saved-practice">Restart this session</button></div><p class="tiny">Restarting begins this session again. Completed lessons, vocabulary progress, and XP stay saved in this browser.</p></section>`;
}
function showSavedSession(){
 if(session)return;
 const history=completedSessionMarkup();if(history)$('#app').insertAdjacentHTML('afterbegin',history);
 try{if(localStorage.getItem(SESSION425+'-before-restart'))$('#app').insertAdjacentHTML('afterbegin','<section class="card"><h3>Return to the attempt before your last restart</h3><button data-undo-restart="true">Restore previous place</button></section>')}catch{}
 const html=savedSessionMarkup();if(!html)return;
 $('#app').insertAdjacentHTML('afterbegin',html);
 $('#resume-saved-practice').onclick=()=>resumeSavedSession(false);
 $('#restart-saved-practice').onclick=()=>resumeSavedSession(true);
}
function resumeSavedSession(restart=false){
 const saved=readActiveSession();if(!saved)return;
 section=Number.isInteger(saved.section)?saved.section:0;
 view=saved.mode==='flash'?'flash':saved.mode==='exam'?'exam':'practice';
 const catalog=sessionCatalog();
 if(restart){
  try{localStorage.setItem(SESSION425+'-before-restart',localStorage.getItem(SESSION425))}catch{storageOK=false;stats()}
  const initial=saved.initial||saved.items;
  const items=initial.map(x=>restoreSessionItem(x,catalog));if(items.some(x=>!x))return;
  session={mode:saved.mode,items:items.map(prepare),index:0,total:items.length,cleared:new Set(),first:{},right:0,graded:false,revealed:false,lessonNumber:saved.lessonNumber,initial};
 }else session={...saved,cleared:new Set(saved.cleared)};
 const wasGraded=!restart&&session.graded,wasRevealed=!restart&&session.revealed;
 renderSession();
 if(wasGraded){
  session.graded=true;session.lastOK=saved.lastOK;
  const x=session.items[session.index];
  document.querySelectorAll('[data-option],[data-blank-word],[data-blank-slot],#check-blanks,#clear-blanks,[data-move],#check-order,[data-word],[data-remove],#check-bank').forEach(b=>b.disabled=true);
  $('#feedback').innerHTML=feedback(x,session.lastOK)+'<button class="primary" id="next">Continue →</button>'+completionBanner(session);
  $('#next').onclick=advance;
 }else if(wasRevealed&&session.mode==='flash'&&$('#flip'))$('#flip').onclick();
 saveActiveSession();$('#app').focus();window.scrollTo(0,0);
}

function completedSetKey(mode,ids){return mode+':'+[...new Set(ids)].sort().join('|')}
function completionReady(s){return s.mode==='exam'?s.index>=s.items.length:s.cleared.size===s.total}
function rememberCompletedSession(s){
 if(!s||!completionReady(s))return null;
 const ids=(s.initial||s.items).map(x=>x.id),key=completedSetKey(s.mode,ids);
 progress.completedSessions??=[];
 let record=progress.completedSessions.find(x=>x.key===key);
 if(s.completionRecorded)return record;
 const number=s.lessonNumber,q=D.questions.find(q=>q.number===number);
 const title=q?q.title:s.mode==='exam'?'Practice exam':s.mode==='flash'?'Flashcard session':'Practice session';
 const result={key,title,mode:s.mode,total:s.total,right:s.right,itemIds:[...new Set(ids)],lessonNumber:number,finishedAt:Date.now(),attempts:(record?.attempts||0)+1};
 if(record)Object.assign(record,result);else{record=result;progress.completedSessions.push(record)}
 s.completionRecorded=true;save();return record;
}
function completionBanner(s){
 if(!completionReady(s))return '';
 rememberCompletedSession(s);
 return `<section class="completion-success" role="status"><h2>✓ ${s.mode==='exam'?'Exam finished':'Completed'}</h2><p>${s.mode==='exam'?`${s.right} of ${s.total} correct on first attempts.`:`All ${s.total} items in this session completed.`}</p><p>This completion is saved. Restarting creates a new attempt and keeps this record.</p><button data-completion-list="true">View saved completions</button></section>`;
}
function completedSessionMarkup(){
 const records=progress.completedSessions||[];
 if(!records.length)return '';
 return `<section class="card completed-history"><h2>✓ Saved completions</h2><p>${records.length} completed practice set${records.length===1?'':'s'}. These records remain when you restart.</p>${[...records].sort((a,b)=>b.finishedAt-a.finishedAt).map(r=>`<article class="completed-record"><span class="lesson-completed">✓ ${r.mode==='exam'?'Exam finished':'Completed'}</span><h3>${esc(r.title)}</h3><p>${r.total} items · ${r.mode==='exam'?`${r.right} correct on first attempts`:'All items completed'} · ${new Date(r.finishedAt).toLocaleString('en-US',{timeZone:'America/New_York'})}</p><button data-view-completion="${esc(r.key)}">View completed session</button></article>`).join('')}</section>`;
}
function viewCompletedSession(key){
 const r=(progress.completedSessions||[]).find(r=>r.key===key);if(!r)return;
 session=null;view='practice';chrome();
 $('#app').innerHTML=`<section class="card completed-history"><span class="lesson-completed">✓ ${r.mode==='exam'?'Exam finished':'Completed'}</span><h1>${esc(r.title)}</h1><p>${r.mode==='exam'?`${r.right} of ${r.total} correct on first attempts.`:`You completed all ${r.total} items in this set.`}</p><p>This saved result remains available after restarting or closing the tab.</p><div class="actions"><button data-completion-list="true">All saved completions</button><button data-review-completion="${esc(r.key)}">Review this set again</button><button data-view="practice">Back to practice</button></div></section>`;
 window.scrollTo(0,0);
}
function reviewCompletedSession(key){
 const r=(progress.completedSessions||[]).find(r=>r.key===key);if(!r)return;
 const catalog=sessionCatalog(),items=r.itemIds.map(id=>catalog.get(id)||catalog.get(id.replace(/-build$/,''))).filter(Boolean);
 if(items.length)start(r.mode,items,r.lessonNumber);
}
function showCompletionList(){session=null;view='practice';chrome();$('#app').innerHTML=completedSessionMarkup()+'<button data-view="practice">Back to practice</button>';window.scrollTo(0,0)}
function restoreBeforeRestart(){
 try{const old=localStorage.getItem(SESSION425+'-before-restart');if(!old)return;localStorage.setItem(SESSION425,old);resumeSavedSession(false)}catch{storageOK=false;stats()}
}

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.completionList){showCompletionList()}else if(b.dataset.viewCompletion){viewCompletedSession(b.dataset.viewCompletion)}else if(b.dataset.reviewCompletion){reviewCompletedSession(b.dataset.reviewCompletion)}else if(b.dataset.undoRestart){restoreBeforeRestart()}else if(b.dataset.restartSession){saveActiveSession();resumeSavedSession(true)}else if(b.dataset.view)navigate(b.dataset.view);else if(b.dataset.lesson)openLesson(+b.dataset.lesson);else if(b.dataset.practiceSection){section=+b.dataset.practiceSection;view='practice';start('practice',shuffle(filtered(D.questions)))}else if(b.dataset.question)start('practice',[D.questions.find(q=>q.number===+b.dataset.question)]);else if(b.dataset.sort)start('practice',[{...D.sorts.find(x=>x.id===b.dataset.sort),kind:'sort'}])});
fetch('cis425-content.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Could not load study content');return r.json()}).then(data=>{D=data;render()}).catch(()=>{$('#app').innerHTML='<section class="card"><h1>Study content could not load</h1><p>Refresh the page to try again. CIS 425 needs cis425-content.json alongside this page.</p><button onclick="location.reload()">Try again</button></section>'});

$("#study-menu").onclick=()=>{const open=$("#study-menu").getAttribute("aria-expanded")!=="true";$("#study-menu").setAttribute("aria-expanded",String(open));$("#nav").setAttribute("data-menu-open",String(open))};
